// #7ca434 עקרונות עיצוב והצעת מיתוג — AC4: утверждённые токены TAQO применены в приложении.
// Источник значений: taqo-tokens.pdf (docs/design/tokens.md @5b3b456): --font Heebo, --ink #0F172A, --accent #4F46E5,
// --radius-card 14px, --radius-control 8px. Кейс: .qa/tests/design-tokens/DT-01. План: specs/design-tokens.md.
// Только просмотр: гость (/login, /signup) и ADMIN компании A (/, /onboarding, /users, /users/invite). @prod-safe.
import { test, expect, Page, Locator } from '@playwright/test';
import { authState } from '../helpers/tenderflow';

type Screen = { path: string; ready: (p: Page) => Locator; control?: (p: Page) => Locator; card?: (p: Page) => Locator };

const GUEST: Screen[] = [
  { path: '/login', ready: (p) => p.getByRole('heading', { name: 'כניסה למערכת', level: 1 }), control: (p) => p.getByRole('textbox', { name: 'אימייל ארגוני' }) },
  { path: '/signup', ready: (p) => p.getByRole('heading', { level: 1 }).first(), control: (p) => p.getByRole('main').getByRole('textbox').first() },
];
const ADMIN: Screen[] = [
  { path: '/', ready: (p) => p.getByRole('heading', { name: 'פיד מכרזים', level: 1 }) },
  { path: '/onboarding', ready: (p) => p.getByRole('heading', { level: 1 }).first() },
  { path: '/users', ready: (p) => p.getByRole('heading', { name: 'משתמשי החברה', level: 1 }), card: (p) => p.getByRole('main').getByRole('table') },
  {
    path: '/users/invite',
    ready: (p) => p.getByRole('heading', { name: 'הזמנת משתמש חדש', level: 1 }),
    control: (p) => p.getByLabel(/שם מלא/),
    card: (p) => p.getByLabel(/שם מלא/),
  },
];

/** CSS-переменные :root, шрифт body и факт загрузки Heebo. */
async function readTokens(page: Page) {
  return page.evaluate(async () => {
    await document.fonts.ready;
    const root = getComputedStyle(document.documentElement);
    const v = (n: string) => root.getPropertyValue(n).trim().toLowerCase();
    return {
      ink: v('--ink'),
      accent: v('--accent'),
      radiusCard: v('--radius-card'),
      radiusControl: v('--radius-control'),
      bodyFont: getComputedStyle(document.body).fontFamily,
      heeboLoaded: [...document.fonts].some((f) => f.family.replace(/["']/g, '') === 'Heebo' && f.status === 'loaded'),
    };
  });
}

/** Скругление ближайшего предка-карточки (радиус ≥ 12px) — карточки TAQO 14px, поля 8px. */
async function cardRadius(loc: Locator): Promise<string | null> {
  return loc.first().evaluate((el) => {
    for (let n = el.parentElement; n && n !== document.body; n = n.parentElement) {
      const r = getComputedStyle(n).borderTopLeftRadius;
      if (parseFloat(r) >= 12) return r;
    }
    return null;
  });
}

async function checkScreen(page: Page, s: Screen) {
  await page.goto(s.path);
  await expect(s.ready(page)).toBeVisible();
  const t = await readTokens(page);
  expect(t.bodyFont, `${s.path}: шрифт body`).toMatch(/^["']?Heebo/);
  expect(t.bodyFont, `${s.path}: нет старых шрифтов`).not.toMatch(/Rubik|Outfit/);
  expect(t.heeboLoaded, `${s.path}: шрифт Heebo загружен`).toBe(true);
  expect(t.ink, `${s.path}: --ink`).toBe('#0f172a');
  expect(t.accent, `${s.path}: --accent`).toBe('#4f46e5');
  expect(t.radiusCard, `${s.path}: --radius-card`).toBe('14px');
  expect(t.radiusControl, `${s.path}: --radius-control`).toBe('8px');
  if (s.control) {
    const r = await s.control(page).first().evaluate((el) => getComputedStyle(el).borderTopLeftRadius);
    expect(r, `${s.path}: скругление поля`).toBe('8px');
  }
  if (s.card) expect(await cardRadius(s.card(page)), `${s.path}: скругление карточки`).toBe('14px');
}

test.describe('טוקני TAQO — מסכים ציבוריים (אורח)', () => {
  for (const s of GUEST) {
    test(`${s.path}: Heebo, --ink #0f172a, --accent #4f46e5, רדיוס שדה 8 #7ca434 @desktop @prod-safe`, async ({ page }) => {
      // DT-01
      await checkScreen(page, s);
    });
  }
});

test.describe('טוקני TAQO — מסכים פנימיים (מנהל חשבון)', () => {
  test.use({ storageState: authState('admin') });
  for (const s of ADMIN) {
    test(`${s.path}: Heebo, --ink #0f172a, --accent #4f46e5, רדיוס כרטיס 14 / שדה 8 #7ca434 @desktop @prod-safe`, async ({ page }) => {
      // DT-01
      await checkScreen(page, s);
    });
  }
});
